import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BWuWLRhz.js";const h=JSON.parse('{"title":"关于","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/user-guide/settings/about.md","filePath":"zh-CN/user-guide/settings/about.md","lastUpdated":1785993908000}'),s={name:"zh-CN/user-guide/settings/about.md"};function n(i,e,l,u,d,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="关于" tabindex="-1">关于 <a class="header-anchor" href="#关于" aria-label="Permalink to &quot;关于&quot;">​</a></h1><p>显示 App、Core、Service、CLI 四个组件的版本号(颜色会反映服务当前是否健康)、Lertaro 的简短说明，以及项目主页和在线使用手册的链接。</p><h2 id="配置文件夹" tabindex="-1">配置文件夹 <a class="header-anchor" href="#配置文件夹" aria-label="Permalink to &quot;配置文件夹&quot;">​</a></h2><p>紧接着下方还有两个链接，用来打开 Lertaro 读写自身配置的文件夹——链接文字本身就是实际路径，点击时如果文件夹还不存在会先创建出来:</p><ul><li><strong>用户配置文件夹</strong> —— 存放 <code>user-settings.json</code> 的每用户文件夹。每次保存设置时，都会先把当前文件轮转备份为 <code>user-settings.json.bak.1</code>(旧的备份依次往后顺延，最多保留到 <code>.bak.5</code>)，再写入新文件，所以一次误改或者保存过程中崩溃，总能找到一份最近的备份恢复。</li><li><strong>系统配置文件夹</strong> —— 后台服务使用的共享、机器级文件夹(<code>machine-settings.json</code>、索引缓存，以及服务端日志)。</li></ul><h2 id="检查更新" tabindex="-1">检查更新 <a class="header-anchor" href="#检查更新" aria-label="Permalink to &quot;检查更新&quot;">​</a></h2><ul><li><strong>检查更新</strong> 按钮 —— 查询是否有新版本;按钮文字本身会反映进度(&quot;正在检查更新...&quot;，之后显示 &quot;已是最新版本&quot;或找到的新版本号)。</li><li>如果非管理员账户无法停止后台服务来原地安装更新，会显示一条警告横幅，并引导你前往手动下载页面。</li><li>一旦发现新版本: <ul><li><strong>静默自动更新</strong> —— 后台下载安装，显示进度条，完成后自动重启 Lertaro。</li><li><strong>前往下载页面</strong> —— 在浏览器中打开 GitHub release 页面，手动安装。</li></ul></li></ul><p>这个页面和<a href="./general.html#系统">通用 → 系统</a>里的<strong>启动时自动检查更新</strong> / <strong>自动静默更新</strong>两个复选框是配套的——那两项控制是否在启动时自动执行这次检查;这个页面则是让你随时手动触发一次。</p>',8)])])}const _=t(s,[["render",n]]);export{h as __pageData,_ as default};
